function lintModules(inputs, entry, globals) {
    const linter = new Linter();
    for (const file of inputs) {
        const allowed = file === entry ? Object.fromEntries(['safeExposeGlobals', ...globals].map(name => [name, 'readonly'])) : {};
        const messages = linter.verify(fs.readFileSync(path.join(ROOT, file), 'utf8'), [{
            languageOptions: { ecmaVersion: 'latest', sourceType: 'module', globals: allowed },
            rules: { 'no-undef': 'error', 'no-unused-vars': 'error', 'no-unreachable': 'error', 'no-empty': 'error',
                complexity: ['error', 10], 'max-depth': ['error', 3], 'max-lines-per-function': ['error', 60], 'max-params': ['error', 5] }
        }], { filename: file });
        if (messages.length) throw new Error(messages.map(m => `${file}:${m.line}: ${m.message}`).join('\n'));
    }
}

function compileEntry({ name, globals, mount, output = `js/${name}.js` }) {
    const entry = `modules/${name}-classic.mjs`;
    const result = buildSync({
        absWorkingDir: ROOT, entryPoints: [entry], bundle: true, write: false, metafile: true,
        platform: 'browser', format: 'iife', target: 'es2020', charset: 'utf8', legalComments: 'inline',
        globalName: mount?.binding,
        banner: { js: `// GENERATED from modules/${name}*.mjs. Edit the ESM sources; run npm run build:modules.` },
        logLevel: 'silent'
    });
    lintModules(Object.keys(result.metafile.inputs), entry, globals);
    // ESM dev spans use preserved comments; restore the release packager's exact markers after bundling.
    const compiled = result.outputFiles[0].text.replaceAll('/*! @dev-only */', '/* @dev-only */')
        .replaceAll('/*! @end-dev-only */', '/* @end-dev-only */');
    if (mount) {
        const template = fs.readFileSync(path.join(ROOT, mount.file), 'utf8').replace(/\r\n/g, '\n');
        if (template.split(mount.marker).length !== 2) throw Error(`${mount.file}: expected exactly one private module mount`);
        return { output, generated: template.replace(mount.marker, () => compiled) };
    }
    return { output, generated: compiled };
}

async function buildModules({ check = false } = {}) {
    // Validate every entry/import before writing any output, so a failed build cannot half-update the game.
    lintModules(dataEntries.map(entry => entry.source), null, []);
    const bundles = [...ENTRIES.map(compileEntry), ...await Promise.all(dataEntries.map(compileData))];
    return bundles.map(({ output, generated }) => {
        const target = path.join(ROOT, output);
        const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') : '';
        if (check && current !== generated) throw new Error(`${output} is stale. Run npm run build:modules before testing or shipping.`);
        if (!check && current !== generated) fs.writeFileSync(target, generated);
        return { output, bytes: Buffer.byteLength(generated), checked: check };
    });
}

if (require.main === module) {
    buildModules({ check: process.argv.includes('--check') })
        .then(result => console.log(JSON.stringify(result)))
        .catch(error => { console.error(error.message); process.exitCode = 1; });
}
module.exports = { buildModules };
